    std::vector<NativeSceneRenderer*> renderers;for(auto& r:source.Renderers)if(r->Visible()&&r->HasGeometry()&&!r->Mesh->Submeshes.empty())renderers.push_back(r.get());if(renderers.empty())throw std::runtime_error("The scene has no visible export geometry.");int shapeFrames=0,materialNumber=0;
